import React from 'react';
import { motion } from 'framer-motion';
import './Hero.css';

const Hero = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.15, delayChildren: 0.2 }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 30, scale: 0.95 },
    visible: {
      opacity: 1,
      y: 0,
      scale: 1,
      transition: { type: 'spring', stiffness: 120, damping: 14 }
    }
  };

  const photoVariants = {
    hidden: { opacity: 0, scale: 0.5, rotate: -15 },
    visible: {
      opacity: 1,
      scale: 1,
      rotate: 0,
      transition: { type: 'spring', stiffness: 100, damping: 12, delay: 0.3 }
    },
    hover: {
      scale: 1.05,
      rotate: 5,
      boxShadow: "0 20px 50px rgba(99, 102, 241, 0.6)",
      transition: { type: 'spring', stiffness: 400, damping: 10 }
    }
  };

  // Crazy floating background shapes
  const FloatingShape = ({ className, delay }) => (
    <motion.div
      className={`floating-shape ${className}`}
      animate={{
        y: [0, -40, 0],
        rotate: [0, 90, 180, 270, 360],
        scale: [1, 1.1, 1],
      }}
      transition={{
        duration: 18,
        delay: delay,
        repeat: Infinity,
        repeatType: "reverse",
        ease: "linear"
      }}
    />
  );

  return (
    <section id="home" className="hero-modern">
      {/* Background Animated Shapes */}
      <FloatingShape className="shape-1" delay={0} />
      <FloatingShape className="shape-2" delay={5} />
      <FloatingShape className="shape-3" delay={2} />
      <div className="hero-glow-overlay"></div>

      <div className="hero-container">
        <motion.div
          className="hero-left-modern"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
        >
          <motion.div className="profile-section-modern" variants={itemVariants}>
            <motion.div
              className="profile-photo-modern"
              variants={photoVariants}
              whileHover="hover"
              whileTap={{ cursor: "grabbing", scale: 0.95 }}
              style={{ cursor: "grab" }}
              drag
              dragConstraints={{ left: -30, right: 30, top: -30, bottom: 30 }}
              dragElastic={0.3}
            >
              <img src="/images/pritish-photo.jpg" alt="Pritish Jadhav" />
              <div className="profile-placeholder">PJ</div>
            </motion.div>
          </motion.div>

          <motion.div className="hero-stats-modern" variants={containerVariants}>
            {[
              { num: '10+', text: 'Projects' },
              { num: '01+', text: 'Years Exp' },
              { num: '100%', text: 'Dedication' }
            ].map((stat, i) => (
              <motion.div
                key={i}
                className="stat-card-modern"
                variants={itemVariants}
                whileHover={{ scale: 1.1, translateY: -10, rotate: i % 2 === 0 ? 2 : -2 }}
                whileTap={{ scale: 0.95 }}
              >
                <h3>{stat.num}</h3>
                <p>{stat.text}</p>
              </motion.div>
            ))}
          </motion.div>
        </motion.div>

        <motion.div
          className="hero-right-modern"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
        >
          <motion.div
            className="hero-badge-modern"
            variants={itemVariants}
            whileHover={{ scale: 1.05 }}
          >
            <motion.span
              animate={{
                boxShadow: ["0px 0px 10px rgba(99, 102, 241, 0.4)", "0px 0px 25px rgba(236, 72, 153, 0.8)", "0px 0px 10px rgba(99, 102, 241, 0.4)"]
              }}
              transition={{ duration: 2, repeat: Infinity }}
            >
              🚀 Available for Work ✨
            </motion.span>
          </motion.div>

          <motion.div className="hero-title-modern" variants={itemVariants}>
            <motion.span
              className="title-greeting"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.5, duration: 0.5 }}
            >
              Hey, I'm
            </motion.span>
            <h1 className="title-name-modern">
              <motion.span
                className="name-part"
                animate={{
                  backgroundPosition: ["0% 50%", "100% 50%", "0% 50%"],
                }}
                transition={{ duration: 5, repeat: Infinity, ease: "linear" }}
              >
                Mr. Pritish Jadhav
              </motion.span>
            </h1>
            <motion.p
              className="title-tagline-modern"
              variants={itemVariants}
            >
              Let's Build Something Brilliant.
            </motion.p>
          </motion.div>

          <motion.div className="hero-roles-modern" variants={containerVariants}>
            {['Full Stack Developer', 'CP Enthusiast', 'Database Administration (DBA)'].map((role, i) => (
              <motion.span
                key={i}
                className="role-badge-modern"
                variants={itemVariants}
                whileHover={{ scale: 1.1, y: -5, backgroundColor: 'rgba(99, 102, 241, 0.2)' }}
                whileTap={{ scale: 0.95 }}
              >
                {role}
              </motion.span>
            ))}
          </motion.div>

          <motion.p className="hero-description-modern" variants={itemVariants}>
            Passionate about creating innovative solutions with AI, Data Science, and Full Stack Development.
            <motion.span
              className="highlight-text"
              initial={{ backgroundColor: "rgba(236,72,153,0)", display: "inline-block" }}
              whileHover={{ backgroundColor: "rgba(236,72,153,0.2)", color: "#fbcfe8", borderRadius: "10px", padding: "0 6px" }}
              transition={{ duration: 0.3 }}
            > Currently leading database operations at CodeChef VIT Pune.</motion.span>
          </motion.p>

          <motion.div className="hero-actions-modern" variants={itemVariants}>
            <motion.a
              href="#contact"
              className="btn-morphing"
              whileHover={{ scale: 1.05, boxShadow: "0 0 30px rgba(99,102,241,0.9)" }}
              whileTap={{ scale: 0.95 }}
            >
              <span>Let's Talk</span>
              <motion.i
                className="fas fa-arrow-right"
                animate={{ x: [0, 8, 0] }}
                transition={{ duration: 1.5, repeat: Infinity }}
              ></motion.i>
            </motion.a>
            <motion.a
              href="#about"
              className="btn-liquid"
              whileHover={{
                scale: 1.05,
                backgroundColor: "rgba(99, 102, 241, 1)",
                color: "#ffffff",
                boxShadow: "0 0 25px rgba(99,102,241,0.6)"
              }}
              whileTap={{ scale: 0.95 }}
            >
              <span>About Me</span>
              <i className="fas fa-user"></i>
            </motion.a>
          </motion.div>

          <motion.div className="hero-social-modern" variants={containerVariants}>
            {[
              { icon: 'fab fa-linkedin-in', link: 'https://linkedin.com/in/pritish-jadhav', title: 'LinkedIn' },
              { icon: 'fab fa-github', link: 'https://github.com/pritishjadhav', title: 'GitHub' },
              { icon: 'fab fa-twitter', link: 'https://x.com/Pritish2006', title: 'X (Twitter)' },
              { icon: 'fab fa-instagram', link: 'https://www.instagram.com/jadhav_pritish_45', title: 'Instagram' }
            ].map((social, index) => (
              <motion.a
                key={index}
                href={social.link}
                target="_blank"
                rel="noopener noreferrer"
                className="social-icon-modern"
                title={social.title}
                variants={itemVariants}
                whileHover={{
                  scale: 1.3,
                  rotate: 360,
                  backgroundColor: "var(--primary-color)",
                  border: "1px solid transparent",
                  boxShadow: "0 0 25px var(--primary-color)"
                }}
                whileTap={{ scale: 0.8, rotate: -90 }}
                transition={{ type: "spring", stiffness: 300, damping: 15 }}
              >
                <i className={social.icon}></i>
              </motion.a>
            ))}
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default Hero;
